import { test, expect } from '@playwright/test';

test.describe('Duplicate Record Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully duplicate an existing record with one click', async ({ page }) => {
    // Verify record list is visible
    const recordList = page.getByRole('region', { name: /record list/i });
    await expect(recordList).toBeVisible();

    // Locate and click the duplicate button on the first record
    const firstRecord = page.getByRole('row', { name: /record 1/i });
    await expect(firstRecord).toBeVisible();

    const duplicateButton = page.getByRole('button', { name: /duplicate/i });
    await expect(duplicateButton).toBeVisible();
    await duplicateButton.click();

    // Wait for duplication modal to appear
    const modal = page.getByRole('dialog', { name: /duplicate record/i });
    await expect(modal).toBeVisible();

    // Verify modal contains correct record details
    const recordNameInput = page.getByLabel(/record name/i);
    await expect(recordNameInput).toHaveValue('Record 1');

    // Verify duplicate button in modal is visible
    const modalDuplicateButton = page.getByRole('button', { name: /duplicate/i });
    await expect(modalDuplicateButton).toBeVisible();

    // Click duplicate button in modal
    await modalDuplicateButton.click();

    // Wait for success notification
    const successMessage = page.getByText(/record duplicated successfully/i);
    await expect(successMessage).toBeVisible();

    // Verify new record appears in list
    const newRecord = page.getByRole('row', { name: /record 1 copy/i });
    await expect(newRecord).toBeVisible();
  });

  test('should handle duplicate record duplication with validation error', async ({ page }) => {
    // Locate and click the duplicate button on the second record
    const secondRecord = page.getByRole('row', { name: /record 2/i });
    await expect(secondRecord).toBeVisible();

    const duplicateButton = page.getByRole('button', { name: /duplicate/i });
    await duplicateButton.click();

    // Wait for duplication modal to appear
    const modal = page.getByRole('dialog', { name: /duplicate record/i });
    await expect(modal).toBeVisible();

    // Clear the record name input
    const recordNameInput = page.getByLabel(/record name/i);
    await recordNameInput.clear();

    // Attempt to duplicate with empty name
    const modalDuplicateButton = page.getByRole('button', { name: /duplicate/i });
    await modalDuplicateButton.click();

    // Verify validation error message appears
    const errorMessage = page.getByText(/record name is required/i);
    await expect(errorMessage).toBeVisible();

    // Verify modal is still open
    await expect(modal).toBeVisible();

    // Verify original record is still present
    const originalRecord = page.getByRole('row', { name: /record 2/i });
    await expect(originalRecord).toBeVisible();

    // Verify no new record was created
    const newRecord = page.getByRole('row', { name: /record 2 copy/i });
    await expect(newRecord).not.toBeVisible();

    // Close modal using cancel button
    const modalCancelButton = page.getByRole('button', { name: /cancel/i });
    await modalCancelButton.click();
    await expect(modal).not.toBeVisible();
  });
});
